// Dieser Code sammelt alle einzelnen Zeilen aus Google Sheets 
// und baut daraus eine saubere JSON-Liste für die KI.

let ausgabenListe = [];
let gesamtKosten = 0;

// Wir gehen durch jede einzelne Zeile aus Google Sheets durch
for (const item of $input.all()) {
  // Pass hier eventuell die Namen (z.B. item.json.Name) an deine Tabellenspalten an!
  let name = item.json.Name || "Unbekannt";
  let betrag = parseFloat(item.json.Betrag) || 0;
  let kategorie = item.json.Kategorie || "Sonstiges";
  let intervall = item.json.Intervall || "monatlich";

  ausgabenListe.push({
    name: name,
    betrag: betrag,
    kategorie: kategorie,
    intervall: intervall
  });

  gesamtKosten += betrag;
}

// Wir geben ein einziges neues Objekt zurück, das die Liste und die Summe enthält
return [{
  json: {
    gesamtKosten: gesamtKosten.toFixed(2),
    anzahlAusgaben: ausgabenListe.length,
    ausgabenListe: ausgabenListe
  }
}];

// 1. Helfer-Funktion zur Umwandlung von Markdown in sauberes HTML
function formatMarkdown(text) {
    if (!text) return '';
    return text
        // Ersetzt fettgedruckten Text (**text**) durch ein schickes, grünes HTML-Strong
        .replace(/\*\*(.*?)\*\*/g, '<strong class="text-emerald-400 font-bold">$1</strong>')
        // Ersetzt einfache Sternchen (* text) am Zeilenanfang durch einen sauberen Listenpunkt
        .replace(/^\s*\*\s*(.*?)$/gm, '• $1')
        // Ersetzt verbleibende einzelne Sternchen (*text*) durch kursiven Text
        .replace(/\*(.*?)\*/g, '<em>$1</em>');
}

// 2. Hier holen wir dynamisch den Text aus deinem AI Agent Schritt
const roherKiText = $input.first().json.output || "Keine Analyse verfügbar.";
const gesamtSumme = "2.088,56 €"; 

// 3. Den Text durch die Formatierungs-Funktion jagen
const saubererKiText = formatMarkdown(roherKiText);

// 4. Das HTML-Template mit dem formatierten Text befüllen
const htmlContent = `
<!DOCTYPE html>
<html lang="de">
<head>
    <meta charset="UTF-8">
    <script src="https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4"></script>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
</head>
<body class="bg-slate-900 text-slate-100 p-6">
    <div class="max-w-5xl mx-auto space-y-8">
        <h1 class="text-3xl font-bold text-emerald-400">Finanz- & Abo-Cockpit</h1>
        <div class="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div class="bg-slate-800 p-6 rounded-2xl">
                <h2 class="text-slate-300">Gesamtausgaben</h2>
                <p class="text-3xl font-bold text-emerald-400">${gesamtSumme}</p>
            </div>
            <div class="md:col-span-2 bg-slate-800 p-6 rounded-2xl">
                <h2 class="text-lg font-semibold mb-4">🤖 KI-Analyse</h2>
                <!-- whitespace-pre-line behält die Absätze bei, während das HTML gerendert wird -->
                <div class="text-slate-300 whitespace-pre-line leading-relaxed">${saubererKiText}</div>
            </div>
        </div>
    </div>
</body>
</html>
`;

// 5. Direkt als fertige Binärdatei ("binary") an Gmail übergeben
return [{
    json: {}, 
    binary: {
        data: {
            data: Buffer.from(htmlContent, 'utf-8').toString('base64'),
            mimeType: 'text/html',
            fileName: 'dashboard.html'
        }
    }
}];
